mapper.select:
SELECT IFNULL(SUM(duration_minutes), 0)
FROM study_checkin
WHERE goal_id = #{goalId}
  AND user_id = #{userId}
  AND deleted = 0

SELECT COUNT(DISTINCT check_date)
FROM study_checkin
WHERE user_id = #{userId}
  AND deleted = 0
  AND DATE_FORMAT(check_date, '%Y-%m') = #{yearMonth}

  AND goal_id = #{goalId}

SELECT check_date AS checkDate, IFNULL(SUM(duration_minutes), 0) AS totalMinutes
FROM study_checkin
WHERE user_id = #{userId}
  AND deleted = 0
  AND check_date BETWEEN #{start} AND #{end}

  AND goal_id = #{goalId}

GROUP BY check_date
ORDER BY check_date ASC
